CREATE TABLE "public"."game_results" (
    "result_id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "game_id" bigint NOT NULL,
    "reporter_id" uuid NOT NULL,
    "winner_id" uuid NOT NULL,
    "loser_id" uuid NOT NULL,
    "status" text NOT NULL DEFAULT 'pending',
    "reviewer_id" uuid,
    "created_at" timestamp with time zone NOT NULL DEFAULT now(),
    "reviewed_at" timestamp with time zone,
    CONSTRAINT "game_results_distinct_players" CHECK ("winner_id" <> "loser_id"),
    CONSTRAINT "game_results_reporter_is_player" CHECK (
        "reporter_id" = "winner_id" OR "reporter_id" = "loser_id"
    ),
    CONSTRAINT "game_results_status_check" CHECK (
        "status" IN ('pending', 'confirmed', 'disputed')
    ),
    CONSTRAINT "game_results_review_fields_check" CHECK (
        (
            "status" = 'pending'
            AND "reviewer_id" IS NULL
            AND "reviewed_at" IS NULL
        )
        OR
        (
            "status" IN ('confirmed', 'disputed')
            AND "reviewer_id" IS NOT NULL
            AND "reviewed_at" IS NOT NULL
        )
    ),
    CONSTRAINT "game_results_game_id_fkey"
        FOREIGN KEY ("game_id") REFERENCES "public"."games"("game_id") ON DELETE CASCADE,
    CONSTRAINT "game_results_reporter_id_fkey"
        FOREIGN KEY ("reporter_id") REFERENCES "auth"."users"("id") ON DELETE CASCADE,
    CONSTRAINT "game_results_reviewer_id_fkey"
        FOREIGN KEY ("reviewer_id") REFERENCES "auth"."users"("id") ON DELETE RESTRICT,
    CONSTRAINT "game_results_winner_rating_fkey"
        FOREIGN KEY ("winner_id", "game_id")
        REFERENCES "public"."ratings"("user_id", "game_id") ON DELETE CASCADE,
    CONSTRAINT "game_results_loser_rating_fkey"
        FOREIGN KEY ("loser_id", "game_id")
        REFERENCES "public"."ratings"("user_id", "game_id") ON DELETE CASCADE
);

CREATE INDEX "game_results_participant_status_idx"
    ON "public"."game_results" ("status", "winner_id", "loser_id");

ALTER TABLE "public"."game_results" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Players can read their game results"
    ON "public"."game_results"
    FOR SELECT
    TO "authenticated"
    USING (
        (SELECT auth.uid()) = "winner_id"
        OR (SELECT auth.uid()) = "loser_id"
    );

CREATE POLICY "Players can report their own results"
    ON "public"."game_results"
    FOR INSERT
    TO "authenticated"
    WITH CHECK (
        (SELECT auth.uid()) = "reporter_id"
        AND (
            (SELECT auth.uid()) = "winner_id"
            OR (SELECT auth.uid()) = "loser_id"
        )
        AND "status" = 'pending'
        AND "reviewer_id" IS NULL
        AND "reviewed_at" IS NULL
    );

GRANT SELECT, INSERT ON TABLE "public"."game_results" TO "authenticated";
GRANT USAGE, SELECT ON SEQUENCE "public"."game_results_result_id_seq" TO "authenticated";

CREATE OR REPLACE FUNCTION "public"."review_game_result"(
    "p_result_id" bigint,
    "p_decision" text
) RETURNS "public"."game_results"
    LANGUAGE "plpgsql"
    SECURITY DEFINER
    SET "search_path" TO ''
AS $$
DECLARE
    result_row public.game_results%ROWTYPE;
    current_user_id uuid := auth.uid();
    old_winner_rating double precision;
    old_winner_rd double precision;
    old_loser_rating double precision;
    old_loser_rd double precision;
    winner_period_rd double precision;
    loser_period_rd double precision;
    winner_g double precision;
    loser_g double precision;
    winner_expected double precision;
    loser_expected double precision;
    winner_d_squared double precision;
    loser_d_squared double precision;
    new_winner_rating double precision;
    new_winner_rd double precision;
    new_loser_rating double precision;
    new_loser_rd double precision;
    q constant double precision := ln(10.0) / 400.0;
    c constant double precision := 63.2;
    default_rd constant double precision := 350.0;
BEGIN
    IF current_user_id IS NULL THEN
        RAISE EXCEPTION 'Authentication required';
    END IF;

    IF p_decision NOT IN ('confirm', 'dispute') THEN
        RAISE EXCEPTION 'Decision must be confirm or dispute';
    END IF;

    SELECT *
    INTO result_row
    FROM public.game_results
    WHERE result_id = p_result_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Result not found';
    END IF;

    IF result_row.status <> 'pending' THEN
        RAISE EXCEPTION 'Result has already been reviewed';
    END IF;

    IF current_user_id = result_row.reporter_id
        OR current_user_id NOT IN (result_row.winner_id, result_row.loser_id)
    THEN
        RAISE EXCEPTION 'Only the opposing player can review this result';
    END IF;

    IF p_decision = 'dispute' THEN
        UPDATE public.game_results
        SET
            status = 'disputed',
            reviewer_id = current_user_id,
            reviewed_at = now()
        WHERE result_id = p_result_id
        RETURNING * INTO result_row;

        RETURN result_row;
    END IF;

    -- Lock both rating rows before calculating either update. The foreign keys
    -- guarantee that both rows exist for this game.
    PERFORM 1
    FROM public.ratings
    WHERE game_id = result_row.game_id
      AND user_id IN (result_row.winner_id, result_row.loser_id)
    ORDER BY user_id
    FOR UPDATE;

    SELECT rating, COALESCE((other_data ->> 'rd')::double precision, default_rd)
    INTO old_winner_rating, old_winner_rd
    FROM public.ratings
    WHERE game_id = result_row.game_id
      AND user_id = result_row.winner_id;

    SELECT rating, COALESCE((other_data ->> 'rd')::double precision, default_rd)
    INTO old_loser_rating, old_loser_rd
    FROM public.ratings
    WHERE game_id = result_row.game_id
      AND user_id = result_row.loser_id;

    winner_period_rd := LEAST(sqrt(power(old_winner_rd, 2) + power(c, 2)), default_rd);
    loser_period_rd := LEAST(sqrt(power(old_loser_rd, 2) + power(c, 2)), default_rd);

    winner_g := 1.0 / sqrt(
        1.0 + (3.0 * power(q, 2) * power(old_loser_rd, 2)) / power(pi(), 2)
    );
    loser_g := 1.0 / sqrt(
        1.0 + (3.0 * power(q, 2) * power(old_winner_rd, 2)) / power(pi(), 2)
    );

    winner_expected := 1.0 / (
        1.0 + power(
            10.0,
            (-winner_g * (old_winner_rating - old_loser_rating)) / 400.0
        )
    );
    loser_expected := 1.0 / (
        1.0 + power(
            10.0,
            (-loser_g * (old_loser_rating - old_winner_rating)) / 400.0
        )
    );

    winner_d_squared := 1.0 / (
        power(q, 2)
        * power(winner_g, 2)
        * winner_expected
        * (1.0 - winner_expected)
    );
    loser_d_squared := 1.0 / (
        power(q, 2)
        * power(loser_g, 2)
        * loser_expected
        * (1.0 - loser_expected)
    );

    new_winner_rating := old_winner_rating
        + (
            q
            / (
                1.0 / power(winner_period_rd, 2)
                + 1.0 / winner_d_squared
            )
        )
        * winner_g
        * (1.0 - winner_expected);
    new_loser_rating := old_loser_rating
        + (
            q
            / (
                1.0 / power(loser_period_rd, 2)
                + 1.0 / loser_d_squared
            )
        )
        * loser_g
        * (0.0 - loser_expected);
    new_winner_rd := sqrt(
        1.0 / (1.0 / power(old_winner_rd, 2) + 1.0 / winner_d_squared)
    );
    new_loser_rd := sqrt(
        1.0 / (1.0 / power(old_loser_rd, 2) + 1.0 / loser_d_squared)
    );

    UPDATE public.ratings
    SET
        rating = new_winner_rating,
        other_data = jsonb_set(other_data::jsonb, '{rd}', to_jsonb(new_winner_rd))::json
    WHERE game_id = result_row.game_id
      AND user_id = result_row.winner_id;

    UPDATE public.ratings
    SET
        rating = new_loser_rating,
        other_data = jsonb_set(other_data::jsonb, '{rd}', to_jsonb(new_loser_rd))::json
    WHERE game_id = result_row.game_id
      AND user_id = result_row.loser_id;

    UPDATE public.game_results
    SET
        status = 'confirmed',
        reviewer_id = current_user_id,
        reviewed_at = now()
    WHERE result_id = p_result_id
    RETURNING * INTO result_row;

    RETURN result_row;
END;
$$;

REVOKE ALL ON FUNCTION "public"."review_game_result"(bigint, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "public"."review_game_result"(bigint, text) TO "authenticated";
